/**
 *
 * Panel is a grouping component providing with content toggle feature.
 *
 * [Live Demo](https://www.primereact.org/panel/)
 *
 * @module PanelRoot
 * @group components
 *
 */
import type { ComponentInstance } from '@primereact/types/core';
import type { MotionOptions } from '@primeuix/motion';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { UsePanelExposes, UsePanelOpenChangeEvent, UsePanelProps, UsePanelState } from '@primereact/types/headless/panel';
/**
 * Defines passthrough(pt) options type in Panel component.
 */
export type PanelRootPassThroughType<E> = PassThroughType<PanelRootInstance, E>;
/**
 * Defines passthrough(pt) options of Panel component.
 */
export interface PanelRootPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: PanelRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the header's DOM element.
     */
    header?: PanelRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the trigger's DOM element.
     */
    trigger?: PanelRootPassThroughType<React.HTMLAttributes<HTMLButtonElement>>;
    /**
     * Used to pass attributes to the title's DOM element.
     */
    title?: PanelRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the content's DOM element.
     */
    content?: PanelRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the content outer wrapper's DOM element.
     */
    contentOuter?: PanelRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the content inner wrapper's DOM element.
     */
    contentInner?: PanelRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the footer's DOM element.
     */
    footer?: PanelRootPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
    /**
     * Used to pass attributes to the indicator's DOM element.
     */
    indicator?: PanelRootPassThroughType<React.HTMLAttributes<HTMLSpanElement>>;
}
/**
 * Event fired when the panel's open state changes.
 * @extends UsePanelOpenChangeEvent
 */
export interface PanelRootOpenChangeEvent extends UsePanelOpenChangeEvent {
}
/**
 * Defines valid properties in Panel component.
 */
export interface PanelRootProps extends BaseComponentProps<PanelRootInstance, Omit<UsePanelProps, 'onOpenChange'>, PanelRootPassThrough> {
    /**
     * When enabled, the content of panel can be expanded and collapsed by clicking the header.
     * @default false
     */
    toggleable?: boolean | undefined;
    /**
     * When enabled, hidden content is not rendered at all. Defaults to false that hides content with css.
     * @default false
     */
    lazy?: boolean | undefined;
    /**
     * Used to configure the motion of the panel content.
     */
    motionProps?: MotionOptions | undefined;
    /**
     * Callback fired when the panel's open state changes.
     * @param event.originalEvent The original event that triggered the change.
     * @param event.value The new value of the panel's open state.
     * @returns void
     */
    onOpenChange?: ((event: PanelRootOpenChangeEvent) => void) | undefined;
}
/**
 * Defines valid state in Panel component.
 * @extends UsePanelState
 */
export interface PanelRootState extends UsePanelState {
}
/**
 * Defines the methods and properties exposed by Panel component.
 * @extends UsePanelExposes
 */
export interface PanelRootExposes extends UsePanelExposes {
}
/**
 * Instance of Panel component.
 */
export type PanelRootInstance = ComponentInstance<PanelRootProps, PanelRootState, PanelRootExposes>;
